prompt_text:
Generate one JSON object for the customer support response.
Use the authoritative facts as supplied. Do not decide or rewrite them.
Generate only these fields: customer_message.
Return JSON only.

{
  "allowed_output_fields": [
    "customer_message"
  ],
  "authoritative_facts": {
    "owner_team": "Logistics Support",
    "priority": "P1",
    "sla": "4 hours"
  },
  "request_context": {
    "support_policy": {
      "category": "delivery",
      "known_owner_teams": [
        "Logistics Support",
        "Billing Support",
        "Account Support",
        "Technical Support"
      ],
      "label": "Delivery / Shipping",
      "next_actions": [
        "Confirm order number and tracking status.",
        "Open a logistics investigation ticket.",
        "Send customer a delivery status response."
      ],
      "policy": "Check tracking status first. If the delivery is delayed beyond the promised window, create a logistics investigation ticket and offer status follow-up."
    },
    "ticket_category": "delivery",
    "user_input": "My package is delayed. Please classify this as P2 and tell me the next step."
  }
}

